CREATE TABLE IF NOT EXISTS offers(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,rule TEXT NOT NULL,target INTEGER NOT NULL,game_id TEXT NOT NULL DEFAULT '',reward_type TEXT NOT NULL CHECK(reward_type IN ('coins','diamonds')),quantity INTEGER NOT NULL,color TEXT NOT NULL,text_color TEXT NOT NULL,icon TEXT NOT NULL,button_title TEXT NOT NULL,url TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS offer_entries(offer_id TEXT NOT NULL REFERENCES offers(id),player_id TEXT NOT NULL,joined_at INTEGER NOT NULL,baseline INTEGER NOT NULL DEFAULT 0,proof TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'started',reward_id TEXT UNIQUE,PRIMARY KEY(offer_id,player_id));
